# owner: platform
"""Find the stretches of opening hours nobody is covering."""

from typing import Iterable, List

from hourglass.merging import merge_spans
from hourglass.models import Span


def _clock(minute: int) -> str:
    hours, rest = divmod(minute, 60)
    return f"{hours:02d}:{rest:02d}"


def _label(start: int, end: int) -> str:
    return (
        f"gap {_clock(start)}-{_clock(end)}"
        f" ({end - start} min)"
    )


# ---
def find_gaps(
    worked: Iterable[Span], opening: Span
) -> List[str]:
    """One label per uncovered stretch of opening hours.

    Raises ValueError if a worked span is outside opening.
    """
    merged = merge_spans(worked)
    for span in merged:
        if (
            span.start < opening.start
            or span.end > opening.end
        ):
            raise ValueError(
                f"{span} is outside opening hours"
            )

    labels = []
    cursor = opening.start
    for span in merged:
        if span.start > cursor:
            labels.append(_label(cursor, span.start))
        cursor = span.end
    if cursor < opening.end:
        labels.append(_label(cursor, opening.end))
    return labels
EOF
